import xarray as xr
import numpy as np
from satpy.readers.fci_l2_nc import FciL2NCAMVFileHandler

class MockNC:
    def __init__(self):
        self.attrs = {'platform': 'MTG', 'data_source': 'FCI'}
    def __getitem__(self, key):
        # Return a DataArray with 'unit' attribute, as it would be in the NetCDF file
        return xr.DataArray(np.zeros((10, 10)), dims=['number_of_images', 'number_of_winds'], attrs={'unit': 'K'})

class MockAMVHandler(FciL2NCAMVFileHandler):
    def __init__(self, filename):
        self.filename = filename
        self.filename_info = {'channel': 'test_channel'}
        self.filetype_info = {}
        # We don't call super().__init__ to avoid potential issues with BaseFileHandler
        # and we just set the attributes we need.
        self.nc = MockNC()

    # We need to override the @cached_property nc because it would try to open a real file
    @property
    def nc(self):
        return MockNC()

def test_amv_units():
    handler = MockAMVHandler("test.nc")
    dataset_id = "test_dataset"
    dataset_info = {"nc_key": "test_var"}

    variable = handler.get_dataset(dataset_id, dataset_info)

    assert 'units' in variable.attrs, "AMV dataset should have 'units' attribute"
    assert 'unit' not in variable.attrs, "AMV dataset should not have 'unit' attribute"

if __name__ == "__main__":
    try:
        test_amv_units()
        print("Tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        import traceback
        traceback.print_exc()
        exit(1)

